// reveal_fee_documents.ts — the customer's invoice and receipt for a paid reveal fee, on the
// QuotesDone template (pdf_native render.ts + doc_template.ts), in English and in full Arabic.
//
// 21 Sep 2026, agent: accountant. The founder (instructions 568, 569): "i didnt like the invoice you
// shared earlier. its not as per our template rules" and "not a single pdf should be generated by our
// team unless its as per our template". What the customer had been handed was Stripe's own invoice
// PDF (TEST invoice PQZAIUL8-0001): Stripe renders that file once, at finalisation, and it still read
// "AED816.37 due … Pay online" with no PAID mark after the card had been charged (customer audit
// 21 Sep, finding 5). The Stripe file stays in finance-docs as the accountant's source record; what a
// person receives is built here.
//
// Modelled on the accountant's commercial invoice (supplier_charge_documents.ts invoiceDocument):
// the same cover, parties, charges table, totals and no-VAT line. No TRN is printed because there is
// none: QuotesDone is not VAT-registered (founder, 14 Sep 2026), so the document is an "Invoice",
// never a "Tax Invoice". ONE INVOICE PER SALE (15 Sep 2026): the number is the one Stripe assigned to
// this payment; a sale Stripe did not invoice prints its payment reference and no invented number.
//
// Pure: a sale record in, renderer bodies out. No I/O, no model.
import { fmtDate } from './supplier_charge_documents.ts';
import { money } from './supplier_charge.ts';
import { FALLBACK } from './doc_template.ts';

export type Lang = 'en' | 'ar';
export const REVEAL_DOC_VERSION = 't2';

export type RevealSale = {
  tx_id: string;
  /** Stripe's invoice number for this payment, or null for a sale paid before invoicing was on. */
  invoice_no: string | null;
  paid_at: string;
  reveal_fee: number;
  processing_fee: number;
  total_charged: number;
  quote_amount: number | null;
  payment_ref: string;
  customer: { name: string | null; email: string; phone: string | null };
  request: { summary: string | null; category: string | null; ref: string };
  /** From the Stripe charge; null when Stripe could not be asked. */
  card: { brand: string; last4: string } | null;
};

// deno-lint-ignore no-explicit-any
type Block = Record<string, any>;
const CO = {
  en: { name: FALLBACK.name, licence: 'Trader License No. 1633275 (Dubai Department of Economy and Tourism)', city: 'Dubai, United Arab Emirates' },
  ar: { name: FALLBACK.name, licence: 'رخصة تاجر رقم 1633275 (دائرة الاقتصاد والسياحة في دبي)', city: 'دبي، الإمارات العربية المتحدة' },
};
const NO_VAT = {
  en: 'QuotesDone Technologies is not registered for VAT; no VAT has been charged on this amount.',
  ar: 'QuotesDone Technologies غير مسجّلة في ضريبة القيمة المضافة؛ ولم تُحتسب أي ضريبة على هذا المبلغ.',
};
const NATURE = {
  en: 'This is the QuotesDone facilitation fee for revealing the selected supplier’s contact details. The amount payable to the supplier for the works is agreed separately and directly between the customer and the supplier.',
  ar: 'هذه رسوم تسهيل من QuotesDone للكشف عن بيانات التواصل مع المورّد المختار. أمّا المبلغ المستحق للمورّد عن الأعمال فيُتفق عليه مباشرة وبشكل منفصل بين العميل والمورّد.',
};
const cardBrand = (b: string) => b ? b[0].toUpperCase() + b.slice(1) : '';
function method(s: RevealSale, lang: Lang) {
  const c = s.card;
  if (lang === 'ar') return c ? `بطاقة ${cardBrand(c.brand)} تنتهي بـ ${c.last4} عبر Stripe` : 'بطاقة عبر Stripe';
  return c ? `${cardBrand(c.brand)} card ending ${c.last4}, via Stripe` : 'Card, via Stripe';
}
/** The reference a document prints: Stripe's invoice number, else the payment reference. */
export function docRef(s: RevealSale) { return s.invoice_no || s.payment_ref; }
function charges(s: RevealSale, lang: Lang): Block {
  const ar = lang === 'ar';
  const cents = (n: number) => Math.round(n * 100);
  // The lines must add up to what the card was charged, or the document is not issued at all.
  if (cents(s.reveal_fee) + cents(s.processing_fee) !== cents(s.total_charged)) {
    throw new Error(`lines do not add up: ${s.reveal_fee} + ${s.processing_fee} != ${s.total_charged}`);
  }
  const what = s.request.summary || s.request.category || (ar ? 'طلب خدمة' : 'service request');
  const base = s.quote_amount ? (ar ? ` — 3% من عرض السعر البالغ ${money(s.quote_amount, 'ar')}` : ` — 3% of the ${money(s.quote_amount)} quotation`) : '';
  const rows = [['1', (ar ? `رسوم الكشف: ${what} (المرجع ${s.request.ref})` : `Reveal fee: ${what} (ref. ${s.request.ref})`) + base, money(s.reveal_fee, lang)]];
  if (s.processing_fee > 0) rows.push(['2', ar ? 'رسوم معالجة البطاقة (Stripe)، تُمرَّر بالتكلفة' : 'Card processing (Stripe), passed on at cost', money(s.processing_fee, lang)]);
  return { t: 'table', head: ar ? ['#', 'البيان', 'المبلغ'] : ['#', 'Description', 'Amount'], rows, widths: [0.06, 0.7, 0.24] };
}
function parties(s: RevealSale, lang: Lang, toLabel: string): Block {
  const ar = lang === 'ar', co = CO[lang], c = s.customer;
  const to = [c.name, c.email, c.phone].filter(Boolean).join(' · ');
  return { t: 'kv', pairs: [[ar ? 'من' : 'From', `${co.name} · ${co.licence}`], [toLabel, to]] };
}
function body(lang: Lang, ref: string, name: string, title: string, kicker: string, subtitle: string, s: RevealSale, meta: string[][], figures: string[][], blocks: Block[]) {
  const ar = lang === 'ar';
  return {
    lang, ref, name, title,
    cover: { kicker, title, subtitle, meta, figures, compact: true },
    control: `${ref} · ${REVEAL_DOC_VERSION} · ${ar ? 'أُصدر في' : 'Issued'} ${fmtDate(s.paid_at, lang)} · ${ar ? 'أعدّه محاسب QuotesDone' : 'Prepared by the QuotesDone accountant'}`,
    blocks, options: { letterhead: true, sign: true, stamp: true },
    ...(ar ? { date_ar: fmtDate(s.paid_at, 'ar') } : { date: fmtDate(s.paid_at, 'en') }),
  };
}

export function revealInvoiceDocument(s: RevealSale, lang: Lang) {
  const ar = lang === 'ar', ref = docRef(s), paid = fmtDate(s.paid_at, lang);
  const T = (en: string, a: string) => ar ? a : en;
  return body(lang, ref, `invoice-${ref}-${lang}-${REVEAL_DOC_VERSION}`, T('Invoice', 'فاتورة'), T('Invoice — paid — not subject to VAT', 'فاتورة — مدفوعة — غير خاضعة لضريبة القيمة المضافة'),
    T(`Reveal fee for request ${s.request.ref}`, `رسوم الكشف عن الطلب ${s.request.ref}`), s,
    [[T('Invoice no.', 'رقم الفاتورة'), s.invoice_no || T('— (see payment ref.)', '— (انظر مرجع الدفع)')], [T('Invoice date', 'تاريخ الفاتورة'), paid], [T('Status', 'الحالة'), T('PAID', 'مدفوعة')], [T('Request ref.', 'مرجع الطلب'), s.request.ref]],
    // No key-figures strip: the meta row says PAID and the totals block ends on "Balance due 0.00";
    // the strip's 84pt is what keeps the signed invoice on one page.
    [],
    [
      parties(s, lang, T('Billed to', 'صادرة إلى')),
      { t: 'section', n: 1, text: T('Charges', 'تفاصيل المبلغ') }, charges(s, lang),
      { t: 'totals', rows: [[T('Total', 'الإجمالي'), money(s.total_charged, lang), false], [T(`Paid on ${paid}`, `المدفوع بتاريخ ${paid}`), '− ' + money(s.total_charged, lang), false], [T('Balance due', 'الرصيد المستحق'), money(0, lang), true]], note: '' },
      { t: 'note', text: NO_VAT[lang] },
      { t: 'kv', pairs: [[T('Paid by', 'طريقة الدفع'), method(s, lang)], [T('Payment reference', 'مرجع الدفع'), s.payment_ref]] },
      { t: 'note', text: (s.invoice_no ? T('The invoice number is the one our payment processor, Stripe, assigned to this payment; this is the only invoice for it. ', 'رقم الفاتورة هو الرقم الذي خصّصه معالج الدفع Stripe لهذه الدفعة، وهذه هي الفاتورة الوحيدة لها. ') : '') + NATURE[lang] },
    ]);
}

export function revealReceiptDocument(s: RevealSale, lang: Lang) {
  const ar = lang === 'ar', ref = docRef(s), paid = fmtDate(s.paid_at, lang);
  const T = (en: string, a: string) => ar ? a : en;
  return body(lang, ref, `receipt-${ref}-${lang}-${REVEAL_DOC_VERSION}`, T('Payment Receipt', 'إيصال دفع'), T('Receipt — payment received', 'إيصال — تم استلام الدفعة'),
    s.invoice_no ? T(`Payment of invoice ${s.invoice_no} — request ${s.request.ref}`, `سداد الفاتورة ${s.invoice_no} — الطلب ${s.request.ref}`) : T(`Reveal fee for request ${s.request.ref}`, `رسوم الكشف عن الطلب ${s.request.ref}`), s,
    [[T('For invoice no.', 'عن الفاتورة رقم'), s.invoice_no || '—'], [T('Date received', 'تاريخ الاستلام'), paid], [T('Amount received', 'المبلغ المستلَم'), money(s.total_charged, lang)], [T('Status', 'الحالة'), T('PAID', 'مدفوعة')]],
    [],
    [
      parties(s, lang, T('Received from', 'استُلم من')),
      { t: 'section', n: 1, text: T('Payment for', 'مقابل') }, charges(s, lang),
      { t: 'totals', rows: [[T('Total received', 'إجمالي المبلغ المستلَم'), money(s.total_charged, lang), true]], note: '' },
      { t: 'kv', pairs: [[T('Paid by', 'طريقة الدفع'), method(s, lang)], [T('Payment reference', 'مرجع الدفع'), s.payment_ref]] },
      { t: 'note', text: (s.invoice_no ? T(`This receipt confirms payment in full of invoice ${s.invoice_no}. It is not a second invoice. `, `يؤكد هذا الإيصال سداد الفاتورة رقم ${s.invoice_no} بالكامل، وهو ليس فاتورة ثانية. `) : T('This receipt confirms payment in full of the amount above. ', 'يؤكد هذا الإيصال سداد المبلغ أعلاه بالكامل. ')) + NO_VAT[lang] },
      { t: 'note', text: NATURE[lang] },
    ]);
}
